    private static List<Long> generateSubsetSums(long[] arr, long m) {
        List<Long> sums = new ArrayList<>();
        sums.add(0L);
        for (long num : arr) {
            int size = sums.size();
            for (int i = 0; i < size; i++) {
                long newSum = (sums.get(i) + num) % m;
                sums.add(newSum);
            }
        }
        return sums;
    }

    private static int binarySearch(List<Long> list, long target) {
        int low = 0, high = list.size() - 1;
        int res = list.size();
        while (low <= high) {
            int mid = (low + high) >>> 1;
            if (list.get(mid) >= target) {
                res = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return res;
    }
}
