        }
        List<Integer> left = new ArrayList<>();
        List<Integer> right = new ArrayList<>();
        int mid = n / 2;
        for (int i = 0; i < mid; i++) left.add(a[i]);
        for (int i = mid; i < n; i++) right.add(a[i]);
        List<Long> leftSums = generateSubsets(left);
        List<Long> rightSums = generateSubsets(right);
        TreeSet<Long> rightSet = new TreeSet<>();
        for (long s : rightSums) {
            rightSet.add(s % m);
        }
        long max = 0;
        for (long s : leftSums) {
            long rem = s % m;
            max = Math.max(max, rem);
            long target = (m - rem) % m;
            Long candidate = rightSet.lower(target);
            if (candidate != null) {
                max = Math.max(max, (rem + candidate) % m);
            }
        }
        System.out.println(max);
    }
    private static List<Long> generateSubsets(List<Integer> list) {
        List<Long> sums = new ArrayList<>();
        int size = list.size();
        for (int mask = 0; mask < (1 << size); mask++) {
            long sum = 0;
            for (int i = 0; i < size; i++) {
                if ((mask & (1 << i)) != 0) {
                    sum += list.get(i);
                }
            }
            sums.add(sum);
        }
        return sums;
    }
