            long target = (m - 1 - remainder) % m;
            // Binary search for the largest value <= target in secondSubsets
            int left = 0, right = secondSubsets.size() - 1;
            long best = 0;
            while (left <= right) {
                int midIdx = (left + right) / 2;
                if (secondSubsets.get(midIdx) <= target) {
                    best = secondSubsets.get(midIdx);
                    left = midIdx + 1;
                } else {
                    right = midIdx - 1;
                }
            }
