            if (remainder > ans) {
                ans = remainder;
            }
        }
        // Also check subsets from the second half alone
        for (long sum : secondSubsets) {
            long remainder = sum % m;
            if (remainder > ans) {
                ans = remainder;
            }
        }
        System.out.println(ans);
