        dp = new long[n + 1][m];
        for (int i = 0; i <= n; i++) {
            Arrays.fill(dp[i], -1);
        }
        dp[0][0] = 0;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (dp[i][j] != -1) {
                    // Don't take the current element
                    if (dp[i + 1][j] == -1 || dp[i + 1][j] < dp[i][j]) {
                        dp[i + 1][j] = dp[i][j];
                    }
                    // Take the current element
                    int newRem = (int) ((j + a[i]) % m);
                    long newVal = dp[i][j] + a[i];
                    if (dp[i + 1][newRem] == -1 || dp[i + 1][newRem] < newVal) {
                        dp[i + 1][newRem] = newVal;
                    }
                }
            }
        }

        long ans = 0;
        for (int j = 0; j < m; j++) {
            if (dp[n][j] != -1) {
                ans = Math.max(ans, dp[n][j] % m);
            }
        }
