    }

    private static long solve(long[] a, long m) {
        int n = a.length;
        int half = n / 2;
        long[] left = new long[1 << half];
        for (int mask = 0; mask < (1 << half); mask++) {
            long sum = 0;
            for (int i = 0; i < half; i++) {
                if ((mask & (1 << i)) != 0) {
                    sum += a[i];
                }
            }
            left[mask] = sum % m;
        }
        Arrays.sort(left);
        long[] right = new long[1 << (n - half)];
        for (int mask = 0; mask < (1 << (n - half)); mask++) {
            long sum = 0;
            for (int i = 0; i < (n - half); i++) {
                if ((mask & (1 << i)) != 0) {
                    sum += a[half + i];
                }
            }
            right[mask] = sum % m;
        }
        Arrays.sort(right);
        long max = 0;
        for (long val : left) {
            max = Math.max(max, val);
        }
        for (long val : right) {
            max = Math.max(max, val);
        }
        for (long val : left) {
            long target = (m - val) % m;
            int idx = Arrays.binarySearch(right, target);
            if (idx < 0) {
                idx = -idx - 1;
            }
            if (idx > 0) {
                long candidate = (val + right[idx - 1]) % m;
                max = Math.max(max, candidate);
            }
            if (idx < right.length) {
                long candidate = (val + right[idx]) % m;
                max = Math.max(max, candidate);
            }
        }
